import{_ as r,C as e,o as i,c as d,E as a,a7 as s}from"./chunks/framework.FWlv_suP.js";const v=JSON.parse('{"title":"Who Called Data Collection","description":"A summary of Who Called data practices.","frontmatter":{"title":"Who Called Data Collection","description":"A summary of Who Called data practices."},"headers":[],"relativePath":"apps/who-called/data-collection.md","filePath":"apps/who-called/data-collection.md"}'),c={name:"apps/who-called/data-collection.md"};function p(h,o,m,u,f,b){const t=e("AppBreadcrumbs"),n=e("AppSubnav"),l=e("CopyStandaloneUrl");return i(),d("div",null,[a(t,{"app-id":"who-called",current:"Data Collection"}),a(n,{"app-id":"who-called"}),a(l,{path:"/data-collection/who-called",label:"Copy standalone data-collection URL","copied-label":"Data-collection URL copied","document-name":"Who Called data-collection page"}),o[0]||(o[0]=s('<h1 id="who-called-data-collection" tabindex="-1">Who Called Data Collection <a class="header-anchor" href="#who-called-data-collection" aria-label="Permalink to &quot;Who Called Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 3, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Who Called stores private contacts, birthday and anniversary dates, reminder preferences, saved messages and their optional bold/highlight ranges, tagged numbers, and settings as AES-GCM-encrypted records in local IndexedDB. Optional PIN verification data is stored as a salted PBKDF2 verifier. Android handles biometric verification without giving the app biometric templates.</p><h2 id="android-call-log" tabindex="-1">Android call log <a class="header-anchor" href="#android-call-log" aria-label="Permalink to &quot;Android call log&quot;">​</a></h2><p>The released Android app uses <code>android.permission.READ_CALL_LOG</code> only after the user enables recent calls and grants Android&#39;s runtime permission. It reads at most 100 recent entries—the number, cached caller name when available, call type, date and time, and duration—to display call history on the homepage and perform local contact or tag matching.</p><p>The list is held temporarily for the app session. It is not saved in the app database, backups, or contact exports and is not sent to the developer. Who Called does not request SMS-reading permission or read SMS or MMS content.</p><h2 id="optional-local-notifications" tabindex="-1">Optional local notifications <a class="header-anchor" href="#optional-local-notifications" aria-label="Permalink to &quot;Optional local notifications&quot;">​</a></h2><p>When a user enables a birthday or anniversary reminder, the Android app schedules a yearly local notification for approximately 6:00 AM and requests notification permission when required. The schedule can include a local contact identifier, the contact&#39;s displayed name, and the birthday or named anniversary needed to compose the notification. Android processes and delivers the notification on the device. This information is not sent to the developer.</p><p>Web builds store reminder preferences for backup and later Android use but do not display browser notifications.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Who Called has no account, developer cloud, analytics, advertising, crash reporting, or tracking service. The developer does not receive application records or call history. Support email contains only what you choose to send.</p><h2 id="external-apps" tabindex="-1">External apps <a class="header-anchor" href="#external-apps" aria-label="Permalink to &quot;External apps&quot;">​</a></h2><p>The phone dialer, SMS composer, WhatsApp, WhatsApp Business, or browser receives the number, draft text, or web address needed for an action you initiate. A file provider you choose receives backups or exports sent to it.</p><h2 id="google-play-data-safety-context" tabindex="-1">Google Play Data safety context <a class="header-anchor" href="#google-play-data-safety-context" aria-label="Permalink to &quot;Google Play Data safety context&quot;">​</a></h2><p>Application records and optional call-history processing remain on the device and are not transmitted to the developer. Google Play defines data collection primarily as transmission off the device, so on-device-only processing is not developer collection. The Play Console declaration must still be reviewed for every released app version and for user-initiated transfers to external apps or file destinations.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',18))])}const g=r(c,[["render",p]]);export{v as __pageData,g as default};
